+import prismaMock from '../prisma-mock';
+import HttpException from '../../app/models/http-exception.model';
+import { deleteComment, getCommentsByArticle } from '../../app/routes/article/article.service';
+
+describe('ArticleService comment soft delete', () => {
+  const now = new Date('2026-10-30T12:00:00.000Z');
+  const slug = 'How-to-train-your-dragon';
+  const commentId = 1;
+  const userId = 123;
+
+  beforeEach(() => {
+    jest.useFakeTimers().setSystemTime(now);
+  });
+
+  afterEach(() => {
+    jest.useRealTimers();
+  });
+
+  describe('deleteComment', () => {
+    test('should set deletedAt and keep the row', async () => {
+      // Given
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue({
+        author: { id: userId, username: 'RealWorld' },
+      });
+
+      // When
+      await deleteComment(commentId, userId);
+
+      // Then
+      expect(prismaMock.comment.update).toHaveBeenCalledWith({
+        where: { id: commentId },
+        data: { deletedAt: now },
+      });
+      expect(prismaMock.comment.delete).not.toHaveBeenCalled();
+    });
+
+    test('should only look up live comments written by the current user', async () => {
+      // Given
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue({
+        author: { id: userId, username: 'RealWorld' },
+      });
+
+      // When
+      await deleteComment(commentId, userId);
+
+      // Then
+      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
+        expect.objectContaining({
+          where: { id: commentId, deletedAt: null, author: { id: userId } },
+        }),
+      );
+    });
+
+    test('should return 404 and change nothing when no live comment of this user matches', async () => {
+      // Given: the lookup finds no live comment of this user (owned by someone else, or already deleted)
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue(null);
+
+      // Then
+      await expect(deleteComment(commentId, userId)).rejects.toMatchObject({ errorCode: 404 });
+      await expect(deleteComment(commentId, userId)).rejects.toBeInstanceOf(HttpException);
+      expect(prismaMock.comment.update).not.toHaveBeenCalled();
+      expect(prismaMock.comment.delete).not.toHaveBeenCalled();
+    });
+  });
+
+  describe('getCommentsByArticle', () => {
+    test('should leave out comments with a deletedAt value', async () => {
+      // Given
+      // @ts-ignore
+      prismaMock.article.findUnique.mockResolvedValue(null);
+
+      // When
+      await getCommentsByArticle(slug, userId);
+
+      // Then
+      expect(prismaMock.article.findUnique).toHaveBeenCalledWith(
+        expect.objectContaining({
+          include: {
+            comments: expect.objectContaining({
+              where: expect.objectContaining({ deletedAt: null }),
+            }),
+          },
+        }),
+      );
+    });
+
+    test('should leave out deleted comments for anonymous readers too', async () => {
+      // Given
+      // @ts-ignore
+      prismaMock.article.findUnique.mockResolvedValue(null);
+
+      // When
+      await getCommentsByArticle(slug);
+
+      // Then
+      expect(prismaMock.article.findUnique).toHaveBeenCalledWith(
+        expect.objectContaining({
+          include: {
+            comments: expect.objectContaining({
+              where: expect.objectContaining({ deletedAt: null }),
+            }),
+          },
+        }),
+      );
+    });
+  });
+});
